slug: async-iterator-missing-enumeratorcancellation
stack: dotnet
topic: async
level: senior
type: find-bug
grading: auto
tags: [iasyncenumerable, async-streams, cancellation, enumerator-cancellation]
code:
  language: csharp
  harness: statements
  source: |
    using CancellationTokenSource cts = new();
    int received = 0;

    try
    {
        await foreach (int item in ProduceAsync().WithCancellation(cts.Token))
        {
            received++;
            if (received == 2)
            {
                cts.Cancel();
            }
        }
    }
    catch (OperationCanceledException)
    {
        Console.WriteLine("canceled");
    }

    Console.WriteLine(received);

    static async IAsyncEnumerable<int> ProduceAsync(CancellationToken token = default)
    {
        for (int i = 1; i <= 5; i++)
        {
            await Task.Delay(10, token);
            yield return i;
        }
    }
bugLineSets: [[22]]
fixedSource: |
  using System.Runtime.CompilerServices;

  using CancellationTokenSource cts = new();
  int received = 0;

  try
  {
      await foreach (int item in ProduceAsync().WithCancellation(cts.Token))
      {
          received++;
          if (received == 2)
          {
              cts.Cancel();
          }
      }
  }
  catch (OperationCanceledException)
  {
      Console.WriteLine("canceled");
  }

  Console.WriteLine(received);

  static async IAsyncEnumerable<int> ProduceAsync([EnumeratorCancellation] CancellationToken token = default)
  {
      for (int i = 1; i <= 5; i++)
      {
          await Task.Delay(10, token);
          yield return i;
      }
  }
fixedExpect: { kind: output, value: "canceled\n2" }
